using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Integration.Aspire;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class EvalTests : EvalTestBase
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static void ClassInitialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine("..", ".eval-results"),
            evaluators: evaluators);
    }

    protected override ReportingConfiguration ReportingConfiguration =>
        s_reportingConfiguration!;

    protected override DistributedApplicationBuilderOptions AppHostOptions =>
        new() { Args = [] };

    protected override string ChatClientResourceName => "chat";

    [TestMethod]
    public async Task AnswersGreeting()
    {
        await using var session = await CreateEvalSessionAsync();

        var response = await session.ChatClient!.GetResponseAsync("Hello, how are you?");

        session.RecordResponse(response);

        await session.EvaluateAsync(
            new EvaluationContext
            {
                UserRequest = "Hello, how are you?",
                ModelResponse = response.Text ?? string.Empty,
            });
    }

    [TestMethod]
    public async Task AnswersFactualQuestion()
    {
        await using var session = await CreateEvalSessionAsync();

        var response = await session.ChatClient!.GetResponseAsync(
            "What is the capital of France?");

        session.RecordResponse(response);

        await session.EvaluateAsync(
            new EvaluationContext
            {
                UserRequest = "What is the capital of France?",
                ModelResponse = response.Text ?? string.Empty,
                GroundTruth = "The capital of France is Paris.",
            });
    }
}

