using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Integration.Aspire;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

public abstract class EvalTestBase
{
    public TestContext TestContext { get; set; } = null!;

    protected abstract ReportingConfiguration ReportingConfiguration { get; }

    protected abstract DistributedApplicationBuilderOptions AppHostOptions { get; }

    protected abstract string ChatClientResourceName { get; }

    protected async Task<EvalSession> CreateEvalSessionAsync()
    {
        var scenario = ReportingConfiguration.CreateScenarioRun(
            TestContext.TestName ?? "unknown");

        var chatClient = await AspireIntegration.CreateChatClientAsync<Projects.MyApp_AppHost>(
            ChatClientResourceName,
            AppHostOptions);

        return new EvalSession(scenario, chatClient);
    }
}

public sealed class EvalSession : IAsyncDisposable
{
    private readonly ScenarioRun _scenarioRun;
    private readonly List<ChatMessage> _messages = [];

    public IChatClient? ChatClient { get; }

    public EvalSession(ScenarioRun scenarioRun, IChatClient chatClient)
    {
        _scenarioRun = scenarioRun;
        ChatClient = chatClient;
    }

    public void RecordResponse(ChatResponse response)
    {
        _messages.AddRange(response.Messages);
    }

    public async Task EvaluateAsync(EvaluationContext context)
    {
        await _scenarioRun.EvaluateAsync(
            _messages,
            additionalContext: [context]);
    }

    public async ValueTask DisposeAsync()
    {
        await _scenarioRun.DisposeAsync();
    }
}

public class EvaluationContext
{
    public string UserRequest { get; set; } = string.Empty;
    public string ModelResponse { get; set; } = string.Empty;
    public string? GroundTruth { get; set; }
}

public class DistributedApplicationBuilderOptions
{
    public string[] Args { get; set; } = [];
}

